    $luckyNumbers = array();

    for ($length = 1; $length <= $n; $length++) {
        for ($cur = 0; $cur < (1 << $length); $cur++) {
            $value = 0;
            for ($j = 0; $j < $length; $j++) {
                if (((1 << $j) & $cur) == (1 << $j))
                    $value += $ten[$j] * 7;
                else
                    $value += $ten[$j] * 4;
            }
            $luckyNumbers[] = (int)$value;
        }
